class Resource {};

// Case 1: Default deleter (size of a raw pointer)
std::unique_ptr<Resource> p1(new Resource);
// sizeof(p1) == sizeof(Resource*)

// Case 2: Custom deleter as a stateless lambda (zero size overhead)
auto stateless_deleter = [](Resource* r){ /* log... */ delete r; };
std::unique_ptr<Resource, decltype(stateless_deleter)> p2(new Resource, stateless_deleter);
// sizeof(p2) == sizeof(Resource*) due to Empty Base Optimization

// Case 3: Custom deleter as a function pointer (size overhead)
void function_deleter(Resource* r) { delete r; }
std::unique_ptr<Resource, void(*)(Resource*)> p3(new Resource, function_deleter);
// sizeof(p3) > sizeof(Resource*). Typically sizeof(Resource*) + sizeof(void(*)())

// Case 4: Custom deleter as a stateful function object (size overhead)
struct StatefulDeleter {
    int log_id; // state
    void operator()(Resource* r) const { /* use log_id */ delete r; }
};
std::unique_ptr<Resource, StatefulDeleter> p4(new Resource, StatefulDeleter{101});
// sizeof(p4) > sizeof(Resource*). Typically sizeof(Resource*) + sizeof(int)
